#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;

class Losowanie {
private:
    static const int N = 10;
    int tab[N + 1];   // +1 na wartownika
public:
    void wypelnij() {
        for (int i = 0; i < N; i++)
            tab[i] = rand() % 100 + 1;
    }

    void wypisz() {
        for (int i = 0; i < N; i++)
            cout << tab[i] << (i < N - 1 ? ", " : "\n");
    }

    int szukaj(int x) {
        tab[N] = x;              // wartownik
        int i = 0;
        while (tab[i] != x) i++;
        return i < N ? i : -1;
    }

    int ileParzystych() {
        int ile = 0;
        for (int i = 0; i < N; i++)
            if (tab[i] % 2 == 0) ile++;
        return ile;
    }
};

int main() {
    srand(time(nullptr));
    Losowanie los;
    los.wypelnij();
    los.wypisz();

    int x;
    cout << "Podaj liczbę do wyszukania: ";
    cin >> x;
    int poz = los.szukaj(x);
    if (poz != -1) cout << "Liczba " << x << " jest na pozycji " << poz << endl;
    else cout << "Nie znaleziono liczby " << x << endl;

    cout << "Liczb parzystych: " << los.ileParzystych() << endl;
    return 0;
}

