    Uczen a("Ola", "Bielecka");
    Uczen b("Igor", "Duda");

    for (int o : {5, 6, 4}) a.dodajOcene(o);
    for (int o : {3, 1, 7})
        if (!b.dodajOcene(o)) cout << "Niepoprawna ocena" << endl;

    a.wypisz();
    cout << (a.czyPromocja() ? "Promocja" : "Brak promocji") << endl;
