    const liczby = oceny.map(Number);
    const suma = liczby.reduce((a, b) => a + b, 0);
    wynik.textContent = 'Średnia: ' + (suma / liczby.length).toFixed(2);

    const promocja = !liczby.includes(1);
    status.textContent = promocja ? 'Promocja' : 'Brak promocji';
    status.style.color = promocja ? 'green' : 'red';
});

