#include <iostream>
#include <string>
using namespace std;

class Szyfrator {
private:
    int klucz;

    char przesun(char c, int k) {
        if (c >= 'a' && c <= 'z') return 'a' + (c - 'a' + k) % 26;
        if (c >= 'A' && c <= 'Z') return 'A' + (c - 'A' + k) % 26;
        return c;
    }

    string przetworz(const string& tekst, int k) {
        string wynik = tekst;
        for (char& c : wynik) c = przesun(c, k);
        return wynik;
    }

public:
    Szyfrator(int klucz) {
        this->klucz = ((klucz % 26) + 26) % 26;   // obsługa ujemnych
    }

    string szyfruj(const string& tekst) { return przetworz(tekst, klucz); }
    string deszyfruj(const string& tekst) { return przetworz(tekst, 26 - klucz); }
};

int main() {
    string tekst;
    int klucz;
    cout << "Podaj tekst: ";
    getline(cin, tekst);
    cout << "Podaj klucz: ";
    cin >> klucz;

    Szyfrator s(klucz);
    string zaszyfrowany = s.szyfruj(tekst);
    cout << "Zaszyfrowany: " << zaszyfrowany << endl;
    cout << "Odszyfrowany: " << s.deszyfruj(zaszyfrowany) << endl;
    return 0;
}

