using System;
using System.Text;

class Szyfrator
{
    private int klucz;

    public Szyfrator(int klucz)
    {
        this.klucz = ((klucz % 26) + 26) % 26;
    }

    private static char Przesun(char c, int k)
    {
        if (c >= 'a' && c <= 'z') return (char)('a' + (c - 'a' + k) % 26);
        if (c >= 'A' && c <= 'Z') return (char)('A' + (c - 'A' + k) % 26);
        return c;
    }

    private static string Przetworz(string tekst, int k)
    {
        var sb = new StringBuilder();
        foreach (char c in tekst) sb.Append(Przesun(c, k));
        return sb.ToString();
    }

    public string Szyfruj(string tekst) => Przetworz(tekst, klucz);
    public string Deszyfruj(string tekst) => Przetworz(tekst, 26 - klucz);
}

class Program
{
    static void Main()
    {
        Console.Write("Podaj tekst: ");
        string tekst = Console.ReadLine();
        Console.Write("Podaj klucz: ");
        int klucz = int.Parse(Console.ReadLine());

        var s = new Szyfrator(klucz);
        string zaszyfrowany = s.Szyfruj(tekst);
        Console.WriteLine($"Zaszyfrowany: {zaszyfrowany}");
        Console.WriteLine($"Odszyfrowany: {s.Deszyfruj(zaszyfrowany)}");
    }
}

